function.arguments:
{"command":"bash -lc 'set -Eeuo pipefail

# 1-3. Disable common firewalls and flush rules
if command -v ufw >/dev/null 2>&1; then
  echo "Disabling ufw";
  ufw --force disable || true;
fi

if command -v systemctl >/dev/null 2>&1; then
  systemctl stop firewalld 2>/dev/null || true;
  systemctl disable firewalld 2>/dev/null || true;
fi

# Fallback: try to stop a running firewalld process if systemd not available
pkill -f firewalld 2>/dev/null || true

# Flush iptables (IPv4/IPv6) and set default policies to ACCEPT
for ipt in iptables ip6tables; do
  if command -v "$ipt" >/dev/null 2>&1; then
    echo "Flushing $ipt and setting policies to ACCEPT";
    $ipt -P INPUT ACCEPT || true;
    $ipt -P FORWARD ACCEPT || true;
    $ipt -P OUTPUT ACCEPT || true;
    $ipt -F || true; $ipt -X || true;
    for t in nat mangle raw security; do $ipt -t $t -F 2>/dev/null || true; $ipt -t $t -X 2>/dev/null || true; done
  fi
done

# Flush nftables ruleset if present
if command -v nft >/dev/null 2>&1; then
  echo "Flushing nftables ruleset";
  nft flush ruleset 2>/dev/null || true
fi

# 4. Test connectivity to the registry health endpoint
set +e
HTTP_CODE=$(curl -sS -o /dev/null -w "%{http_code}" https://registry.intra:443/health)
CURL_RC=$?
set -e

echo "curl exit code: $CURL_RC, http code: $HTTP_CODE"
exit 0'"}

